// Prepare Gemini Audio Payload for Algerian Darija
const binaryData = items[0].binary?.data;
if (!binaryData) {
  throw new Error('No audio/video file provided in binary property "data"');
}

const base64Audio = binaryData.data;
const mimeType = binaryData.mimeType || 'audio/mp3';
const query = $input.item.json.query || {};
const dialect = query.dialect || 'General Algerian';

const prompt = `You are an expert transcriber specialized in Algerian Arabic (الدارجة الجزائرية - Darija).\nListen to the audio and transcribe accurately into Arabic script with exact word timestamps.\nDialect: ${dialect}.\nReturn STRICT JSON format only:\n{\n  "language": "ar-DZ",\n  "text": "...",\n  "segments": [\n    {\n      "id": 0,\n      "start": 0.00,\n      "end": 2.50,\n      "text": "واش راك خويا",\n      "words": [\n        {"word": "واش", "start": 0.00, "end": 0.60},\n        {"word": "راك", "start": 0.60, "end": 1.20},\n        {"word": "خويا", "start": 1.20, "end": 2.50}\n      ]\n    }\n  ]\n}`;

return [{
  json: {
    contents: [
      {
        parts: [
          {
            inline_data: {
              mime_type: mimeType,
              data: base64Audio
            }
          },
          {
            text: prompt
          }
        ]
      }
    ],
    generationConfig: {
      temperature: 0.2,
      responseMimeType: 'application/json'
    },
    query: query
  }
}];

// Parse Gemini Response and Build ASS Subtitles
const response = $input.item.json;
const candidates = response.candidates || [];
if (!candidates.length) {
  throw new Error('Gemini API returned no candidates');
}

const rawText = candidates[0].content?.parts?.[0]?.text || '{}';
let data = {};
try {
  data = JSON.parse(rawText);
} catch (e) {
  const clean = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  data = JSON.parse(clean);
}

const segments = data.segments || [];

function formatAssTime(seconds) {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  const cs = Math.floor((seconds % 1) * 100);
  return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(cs).padStart(2, '0')}`;
}

let assContent = `[Script Info]\nScriptType: v4.00+\nPlayResX: 1080\nPlayResY: 1920\n\n[V4+ Styles]\nFormat: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\nStyle: Default,Cairo,56,&H00FFFFFF,&H0000E6FF,&H00000000,&H00000000,-1,0,0,0,100,100,0,0,1,3.5,2.0,2,30,30,90,1\n\n[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n`;

const allWords = [];
for (const seg of segments) {
  if (seg.words && seg.words.length) {
    allWords.push(...seg.words);
  } else {
    const ws = (seg.text || '').split(' ');
    const dur = (seg.end - seg.start) / ws.length;
    let cur = seg.start;
    for (const w of ws) {
      allWords.push({ word: w, start: cur, end: cur + dur });
      cur += dur;
    }
  }
}

// Chunk into 3 words per line
const wordsPerLine = 3;
for (let i = 0; i < allWords.length; i += wordsPerLine) {
  const chunk = allWords.slice(i, i + wordsPerLine);
  for (let j = 0; j < chunk.length; j++) {
    const active = chunk[j];
    const next = chunk[j + 1];
    const wEnd = next ? next.start : active.end;
    const startStr = formatAssTime(active.start);
    const endStr = formatAssTime(wEnd);

    const formatted = chunk.map((w, idx) => {
      return idx === j ? `{\\c&H0000E6FF\\fscx115\\fscy115}${w.word}{\\c&H00FFFFFF\\fscx100\\fscy100}` : `{\\c&H00FFFFFF}${w.word}`;
    }).join(' ');

    assContent += `Dialogue: 0,${startStr},${endStr},Default,,0,0,0,,${formatted}\n`;
  }
}

return [{
  json: {
    transcription: data,
    assContent: assContent
  }
}];
